"""Tkinter user interface for the Space Fractions desktop application.

Implements the screens named in the summary (C18): intro (movie placeholder),
main menu, game, ending (feedback), help, and admin question management.
"""

import tkinter as tk
from tkinter import messagebox

from spacefractions.admin.service import AdminService
from spacefractions.game.service import GameService
from spacefractions.help import HELP_TEXT
from spacefractions.persistence import connect, init_db
from spacefractions.question.repository import QuestionRepository
from spacefractions.question.service import QuestionService
from spacefractions.user.service import UserService


class SpaceFractionsApp:
    def __init__(self, root, conn):
        self.root = root
        self.conn = conn
        init_db(conn)

        self.question_repo = QuestionRepository(conn)
        self.questions = QuestionService(self.question_repo)
        self.games = GameService(self.question_repo)
        self.users = UserService(conn)
        self.admin = AdminService(self.questions)

        self.root.title("Space Fractions")
        self.game = None
        self._frame = None
        self._seed_questions()
        self.show_intro()

    # ---- screen helpers ----
    def _clear(self):
        if self._frame is not None:
            self._frame.destroy()
        self._frame = tk.Frame(self.root)
        self._frame.pack(fill="both", expand=True, padx=12, pady=12)

    def _button(self, text, command):
        return tk.Button(self._frame, text=text, command=command)

    def _label(self, text, **kwargs):
        return tk.Label(self._frame, text=text, wraplength=480, **kwargs)

    def _seed_questions(self):
        if self.questions.all_questions():
            return
        seed = [
            ("1/2 + 1/2 = ?", ["1", "2", "1/4", "1/2"], 0),
            ("3/4 - 1/4 = ?", ["1", "1/2", "3/4", "2/4"], 1),
            ("1/3 * 2 = ?", ["1/3", "2/3", "1/6", "3/2"], 1),
            ("2/5 + 1/5 = ?", ["3/5", "2/5", "1/5", "3/10"], 0),
        ]
        for prompt, options, correct in seed:
            self.questions.add_question(prompt, options, correct)

    # ---- screens ----
    def show_intro(self):
        self._clear()
        self._label("Space Fractions", font=("Arial", 24)).pack(pady=20)
        self._label("Intro movie placeholder: a short animation about fraction-solving.").pack(pady=10)
        self._button("Continue", self.show_menu).pack(pady=20)

    def show_menu(self):
        self._clear()
        self._label("Main Menu", font=("Arial", 20)).pack(pady=20)
        self._button("Play Game", self.show_game).pack(pady=6)
        self._button("View Score", self.show_score).pack(pady=6)
        self._button("View Help", self.show_help).pack(pady=6)
        self._button("Admin", self.show_admin).pack(pady=6)
        self._button("Quit", self.root.destroy).pack(pady=6)

    def show_help(self):
        self._clear()
        self._label("Help", font=("Arial", 20)).pack(pady=10)
        self._label(HELP_TEXT, justify="left").pack(pady=10)
        self._button("Back", self.show_menu).pack(pady=10)

    def show_score(self):
        self._clear()
        self._label("Score", font=("Arial", 20)).pack(pady=10)
        if self.game is not None:
            self._label(f"Current score: {self.game.view_score()}").pack(pady=10)
        else:
            self._label("No game played yet.").pack(pady=10)
        self._button("Back", self.show_menu).pack(pady=10)

    def show_admin(self):
        self._clear()
        self._label("Admin - Update Questions", font=("Arial", 20)).pack(pady=10)
        self._label("Existing questions:").pack(pady=4)
        for question in self.questions.all_questions():
            self._label(f"  [{question.id}] {question.get_prompt()}").pack(anchor="w")

        tk.Label(self._frame, text="Prompt:").pack(anchor="w", pady=(10, 0))
        prompt_var = tk.StringVar()
        tk.Entry(self._frame, textvariable=prompt_var, width=50).pack(anchor="w")

        tk.Label(self._frame, text="Options (comma-separated):").pack(anchor="w", pady=(10, 0))
        options_var = tk.StringVar()
        tk.Entry(self._frame, textvariable=options_var, width=50).pack(anchor="w")

        tk.Label(self._frame, text="Correct option index (0-based):").pack(anchor="w", pady=(10, 0))
        correct_var = tk.StringVar()
        tk.Entry(self._frame, textvariable=correct_var, width=10).pack(anchor="w")

        def add():
            prompt = prompt_var.get().strip()
            options = [option.strip() for option in options_var.get().split(",") if option.strip()]
            try:
                correct = int(correct_var.get())
            except ValueError:
                messagebox.showerror("Error", "Correct index must be an integer.")
                return
            if not prompt or not options or not (0 <= correct < len(options)):
                messagebox.showerror("Error", "Provide a prompt, at least one option, and a valid index.")
                return
            self.admin.add_question(prompt, options, correct)
            self.show_admin()

        self._button("Add Question", add).pack(pady=10)
        self._button("Back", self.show_menu).pack(pady=6)

    def show_game(self):
        self.game = self.games.play()
        self._render_question()

    def _render_question(self):
        self._clear()
        question = self.game.current_question()
        if question is None:
            self.show_ending()
            return
        current, total = self.game.progress()
        self._label(f"Question {current + 1} of {total}").pack(pady=6)
        self._label(question.get_prompt(), font=("Arial", 16)).pack(pady=10)
        for index, option in enumerate(question.get_options()):
            self._button(option, lambda i=index: self._answer(i)).pack(pady=3, fill="x")

    def _answer(self, index):
        self.game.submit_answer(index)
        if self.game.is_finished():
            self.show_ending()
        else:
            self._render_question()

    def show_ending(self):
        self._clear()
        score = self.game.view_score()
        total = len(self.game.questions)
        self._label("Game Over", font=("Arial", 24)).pack(pady=20)
        self._label(f"Your score: {score} / {total}").pack(pady=10)
        if total and score == total:
            feedback = "Perfect! Great fraction-solving!"
        elif total and score >= total / 2:
            feedback = "Good job! Keep practising."
        else:
            feedback = "Keep trying - practice makes progress!"
        self._label(feedback).pack(pady=10)
        self._button("Play Again", self.show_game).pack(pady=6)
        self._button("Main Menu", self.show_menu).pack(pady=6)


def run(db_path=None):
    """Start the desktop application (creates the window and runs mainloop)."""
    conn = connect(db_path)
    try:
        root = tk.Tk()
        SpaceFractionsApp(root, conn)
        root.mainloop()
    finally:
        conn.close()
